/**
 * WissOS 2.0 – Custom Offline Markdown Parser
 * High-performance, lightweight markdown parser providing offline marked.js compatible API.
 * CC-BY-SA 4.0 Wolf Sebastian (2026)
 */

(function () {
  'use strict';

  window.marked = {
    parse: function (markdown) {
      if (!markdown) return '';
      
      let html = markdown;

      // Normalize carriage returns
      html = html.replace(/\r\n/g, '\n');

      // Headings: ## Heading -> <h3>Heading</h3>
      html = html.replace(/^##\s+(.+)$/gm, '<h3>$1</h3>');
      html = html.replace(/^###\s+(.+)$/gm, '<h4>$1</h4>');

      // Bold: **text** -> <strong>text</strong>
      html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

      // Italic: *text* -> <em>text</em>
      html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');

      // Lists: - item -> <li>item</li>
      html = html.replace(/^\-\s+(.+)$/gm, '<li>$1</li>');

      // Blockquote styling
      html = html.replace(/^>\s+(.+)$/gm, '<blockquote style="border-left:4px solid var(--color-accent); padding-left:8px; margin: 8px 0; font-style:italic;">$1</blockquote>');

      // Wrap list blocks: matches continuous groups of <li>
      html = html.replace(/(?:^|\n)(<li>[\s\S]*?<\/li>)(?=\n[^<]|$)/g, function (match, p1) {
        return '\n<ul style="padding-left:20px; margin: 8px 0;">' + p1 + '</ul>';
      });

      // Split lines and wrap raw text lines in <p>
      let lines = html.split('\n');
      for (let i = 0; i < lines.length; i++) {
        let trimmed = lines[i].trim();
        if (trimmed && 
            !trimmed.startsWith('<h') && 
            !trimmed.startsWith('<li') && 
            !trimmed.startsWith('<ul') && 
            !trimmed.startsWith('</ul') && 
            !trimmed.startsWith('<block') && 
            !trimmed.startsWith('</block')) {
          lines[i] = '<p style="margin-bottom:8px;">' + lines[i] + '</p>';
        }
      }

      return lines.join('\n');
    }
  };
})();
